INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000006', '22222222-2222-2222-2222-000000000001', 'In the context of HTML5 (Semantics & Accessibility), what is the primary architectural purpose or defining characteristic?', '["To encapsulate and modularize Semantics & Accessibility logic for predictable, isolated state and high maintainability.","To eliminate all CPU and memory overhead by converting dynamic execution to purely static bytecode.","To enforce a synchronous blocking execution model across the entire client and server pipeline.","To bypass network security boundaries and grant unrestricted kernel access."]'::jsonb, 0, 'The core design goal of Semantics & Accessibility within HTML5 is providing structured encapsulation, predictability, and clean abstraction boundaries.', 'easy', 'HTML5', 'Semantics & Accessibility', 'question_bank', 'Understand the fundamental architecture and purpose of Semantics & Accessibility.', '5a1fbf135fa0664b6a569bf92ace0d68300c84f3bf384245ae98a334f24f0977')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000007', '22222222-2222-2222-2222-000000000001', 'When implementing Semantics & Accessibility in HTML5, which of the following is considered an anti-pattern or common mistake?', '["Strictly validating input data and handling asynchronous error boundaries gracefully.","Directly mutating internal shared state or ignoring cleanup in asynchronous lifecycles.","Using deterministic pure functions and declarative API contracts.","Profiling execution times and setting appropriate timeout thresholds."]'::jsonb, 1, 'Direct mutation of shared state or leaking asynchronous resources without proper teardown leads to race conditions, memory leaks, and hard-to-trace bugs.', 'medium', 'HTML5', 'Semantics & Accessibility', 'question_bank', 'Identify common anti-patterns and memory/concurrency pitfalls in Semantics & Accessibility.', 'f4a6c05acb9924dbdd2b9d410a496f5e7e2337f419d572bb40d40d65e875b84b')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000008', '22222222-2222-2222-2222-000000000001', 'What is the expected behavior or time/space tradeoff when optimizing Semantics & Accessibility under high load?', '["Memory consumption is completely reduced to zero while throughput increases infinitely.","Trading additional memory/caching to achieve lower latency and avoid redundant CPU-intensive computations.","Switching to an unindexed linear scan to reduce disk I/O overhead.","Removing thread pools and running all concurrent tasks on a single unmonitored thread."]'::jsonb, 1, 'Classic performance optimization in HTML5 leverages space-time tradeoffs: caching computed state or indexing reduces CPU bottleneck at the expense of bounded memory.', 'medium', 'HTML5', 'Semantics & Accessibility', 'question_bank', 'Evaluate algorithmic and resource trade-offs in Semantics & Accessibility.', 'fad75194693fb9bf8a491ed0f0378c7667bd627dffe66c7c999d1ceb51298e02')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000009', '22222222-2222-2222-2222-000000000001', 'Which code construct or design pattern is most standard when working with Semantics & Accessibility?', '["Relying on arbitrary global variables across unrelated modules.","Adhering to Single Responsibility and using structured abstractions with proper error handling.","Hardcoding configuration secrets and database credentials inside client files.","Suppressing exceptions using empty catch blocks to ensure silence."]'::jsonb, 1, 'Modern engineering standards require adherence to SOLID principles, separation of concerns, and robust error propagation.', 'hard', 'HTML5', 'Semantics & Accessibility', 'question_bank', 'Apply best-practice design patterns for Semantics & Accessibility.', 'dd31352650cbd10c6242d659191f57c96b477599979d9178ac82fd120faa26bb')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000010', '22222222-2222-2222-2222-000000000001', 'During technical interviews, how should an engineer explain the key advantage of Semantics & Accessibility over traditional alternatives?', '["It guarantees 100% bug-free execution without requiring any automated tests or peer reviews.","It offers better scalability, modularity, and operational clarity while handling edge cases predictably.","It requires zero compilation or interpretation time regardless of codebase size.","It replaces all database, network, and hardware layers with a single script."]'::jsonb, 1, 'In engineering interviews, evaluating Semantics & Accessibility centers on scalable architecture, decoupling, maintainability, and predictable failure modes.', 'advanced', 'HTML5', 'Semantics & Accessibility', 'question_bank', 'Articulate architectural advantages and real-world considerations in interviews.', '47ab53e3accc01955d689231bc447b9efcb29a34cd8bdfd2890719e7a90d6459')
ON CONFLICT (question_hash) DO NOTHING;
