ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000106', '22222222-2222-2222-2222-000000000021', 'In the context of Python Basics (Data Types), what is the primary architectural purpose or defining characteristic?', '["To encapsulate and modularize Data Types logic for predictable, isolated state and high maintainability.","To eliminate all CPU and memory overhead by converting dynamic execution to purely static bytecode.","To enforce a synchronous blocking execution model across the entire client and server pipeline.","To bypass network security boundaries and grant unrestricted kernel access."]'::jsonb, 0, 'The core design goal of Data Types within Python Basics is providing structured encapsulation, predictability, and clean abstraction boundaries.', 'easy', 'Python Basics', 'Data Types', 'question_bank', 'Understand the fundamental architecture and purpose of Data Types.', '17bbf5cc7eaa30303514795b04c46a2d5882b43c91d05d90405c72dc977dcb45')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000107', '22222222-2222-2222-2222-000000000021', 'When implementing Data Types in Python Basics, which of the following is considered an anti-pattern or common mistake?', '["Strictly validating input data and handling asynchronous error boundaries gracefully.","Directly mutating internal shared state or ignoring cleanup in asynchronous lifecycles.","Using deterministic pure functions and declarative API contracts.","Profiling execution times and setting appropriate timeout thresholds."]'::jsonb, 1, 'Direct mutation of shared state or leaking asynchronous resources without proper teardown leads to race conditions, memory leaks, and hard-to-trace bugs.', 'medium', 'Python Basics', 'Data Types', 'question_bank', 'Identify common anti-patterns and memory/concurrency pitfalls in Data Types.', '364bbc6a262e5b596307e7ddb9ff277e312650b997d588dc25ab7642b5f491d5')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000108', '22222222-2222-2222-2222-000000000021', 'What is the expected behavior or time/space tradeoff when optimizing Data Types under high load?', '["Memory consumption is completely reduced to zero while throughput increases infinitely.","Trading additional memory/caching to achieve lower latency and avoid redundant CPU-intensive computations.","Switching to an unindexed linear scan to reduce disk I/O overhead.","Removing thread pools and running all concurrent tasks on a single unmonitored thread."]'::jsonb, 1, 'Classic performance optimization in Python Basics leverages space-time tradeoffs: caching computed state or indexing reduces CPU bottleneck at the expense of bounded memory.', 'medium', 'Python Basics', 'Data Types', 'question_bank', 'Evaluate algorithmic and resource trade-offs in Data Types.', 'cc24492ebb40fb84b9e96b3098879c35d1bddb8de7c7f5a4331becf897f65a30')
ON CONFLICT (question_hash) DO NOTHING;
