INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000136', '22222222-2222-2222-2222-000000000027', 'In the context of Data Analysis (Statistical EDA), what is the primary architectural purpose or defining characteristic?', '["To encapsulate and modularize Statistical EDA logic for predictable, isolated state and high maintainability.","To eliminate all CPU and memory overhead by converting dynamic execution to purely static bytecode.","To enforce a synchronous blocking execution model across the entire client and server pipeline.","To bypass network security boundaries and grant unrestricted kernel access."]'::jsonb, 0, 'The core design goal of Statistical EDA within Data Analysis is providing structured encapsulation, predictability, and clean abstraction boundaries.', 'easy', 'Data Analysis', 'Statistical EDA', 'question_bank', 'Understand the fundamental architecture and purpose of Statistical EDA.', 'a501f869da5b90ac0ba222ba5da7f1e625d78a3bd1aa78b7ad377a72f8228b23')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000137', '22222222-2222-2222-2222-000000000027', 'When implementing Statistical EDA in Data Analysis, which of the following is considered an anti-pattern or common mistake?', '["Strictly validating input data and handling asynchronous error boundaries gracefully.","Directly mutating internal shared state or ignoring cleanup in asynchronous lifecycles.","Using deterministic pure functions and declarative API contracts.","Profiling execution times and setting appropriate timeout thresholds."]'::jsonb, 1, 'Direct mutation of shared state or leaking asynchronous resources without proper teardown leads to race conditions, memory leaks, and hard-to-trace bugs.', 'medium', 'Data Analysis', 'Statistical EDA', 'question_bank', 'Identify common anti-patterns and memory/concurrency pitfalls in Statistical EDA.', '7d0566b2435247a35227cada141c44eb743a797d2017591ee9b19c630075b3e6')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000138', '22222222-2222-2222-2222-000000000027', 'What is the expected behavior or time/space tradeoff when optimizing Statistical EDA under high load?', '["Memory consumption is completely reduced to zero while throughput increases infinitely.","Trading additional memory/caching to achieve lower latency and avoid redundant CPU-intensive computations.","Switching to an unindexed linear scan to reduce disk I/O overhead.","Removing thread pools and running all concurrent tasks on a single unmonitored thread."]'::jsonb, 1, 'Classic performance optimization in Data Analysis leverages space-time tradeoffs: caching computed state or indexing reduces CPU bottleneck at the expense of bounded memory.', 'medium', 'Data Analysis', 'Statistical EDA', 'question_bank', 'Evaluate algorithmic and resource trade-offs in Statistical EDA.', '58eaf7210541fbfd437879c68f2856f39158ea46ae2989f09b3904e88fcea06e')
