VALUES ('33333333-3333-3333-3333-000000000162', '22222222-2222-2222-2222-000000000032', 'When implementing DP Patterns in Dynamic Programming, which of the following is considered an anti-pattern or common mistake?', '["Strictly validating input data and handling asynchronous error boundaries gracefully.","Directly mutating internal shared state or ignoring cleanup in asynchronous lifecycles.","Using deterministic pure functions and declarative API contracts.","Profiling execution times and setting appropriate timeout thresholds."]'::jsonb, 1, 'Direct mutation of shared state or leaking asynchronous resources without proper teardown leads to race conditions, memory leaks, and hard-to-trace bugs.', 'medium', 'Dynamic Programming', 'DP Patterns', 'question_bank', 'Identify common anti-patterns and memory/concurrency pitfalls in DP Patterns.', 'f68339253f64ea4c3962b3212e2810b2a05972b6577312036a408c2de6da1d7d')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000163', '22222222-2222-2222-2222-000000000032', 'What is the expected behavior or time/space tradeoff when optimizing DP Patterns under high load?', '["Memory consumption is completely reduced to zero while throughput increases infinitely.","Trading additional memory/caching to achieve lower latency and avoid redundant CPU-intensive computations.","Switching to an unindexed linear scan to reduce disk I/O overhead.","Removing thread pools and running all concurrent tasks on a single unmonitored thread."]'::jsonb, 1, 'Classic performance optimization in Dynamic Programming leverages space-time tradeoffs: caching computed state or indexing reduces CPU bottleneck at the expense of bounded memory.', 'medium', 'Dynamic Programming', 'DP Patterns', 'question_bank', 'Evaluate algorithmic and resource trade-offs in DP Patterns.', '4cef5571d8eff838a79563ad2e8b6c59f3e8715f28d6b2cf41cfa2c3f5e63f30')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
