ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000165', '22222222-2222-2222-2222-000000000032', 'During technical interviews, how should an engineer explain the key advantage of DP Patterns over traditional alternatives?', '["It guarantees 100% bug-free execution without requiring any automated tests or peer reviews.","It offers better scalability, modularity, and operational clarity while handling edge cases predictably.","It requires zero compilation or interpretation time regardless of codebase size.","It replaces all database, network, and hardware layers with a single script."]'::jsonb, 1, 'In engineering interviews, evaluating DP Patterns centers on scalable architecture, decoupling, maintainability, and predictable failure modes.', 'advanced', 'Dynamic Programming', 'DP Patterns', 'question_bank', 'Articulate architectural advantages and real-world considerations in interviews.', '91e0445a21c42495495fe8c299569593b854bb817a072251b135811454eed7a9')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
