VALUES ('33333333-3333-3333-3333-000000000190', '22222222-2222-2222-2222-000000000037', 'During technical interviews, how should an engineer explain the key advantage of Regression & Classification over traditional alternatives?', '["It guarantees 100% bug-free execution without requiring any automated tests or peer reviews.","It offers better scalability, modularity, and operational clarity while handling edge cases predictably.","It requires zero compilation or interpretation time regardless of codebase size.","It replaces all database, network, and hardware layers with a single script."]'::jsonb, 1, 'In engineering interviews, evaluating Regression & Classification centers on scalable architecture, decoupling, maintainability, and predictable failure modes.', 'advanced', 'Machine Learning', 'Regression & Classification', 'question_bank', 'Articulate architectural advantages and real-world considerations in interviews.', '7765a63e046baea1b78a59134bcb43bc09a834a1bf5361989a0b1166b00157cc')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000191', '22222222-2222-2222-2222-000000000038', 'In the context of Machine Learning (Clustering & PCA), what is the primary architectural purpose or defining characteristic?', '["To encapsulate and modularize Clustering & PCA logic for predictable, isolated state and high maintainability.","To eliminate all CPU and memory overhead by converting dynamic execution to purely static bytecode.","To enforce a synchronous blocking execution model across the entire client and server pipeline.","To bypass network security boundaries and grant unrestricted kernel access."]'::jsonb, 0, 'The core design goal of Clustering & PCA within Machine Learning is providing structured encapsulation, predictability, and clean abstraction boundaries.', 'easy', 'Machine Learning', 'Clustering & PCA', 'question_bank', 'Understand the fundamental architecture and purpose of Clustering & PCA.', '717e2684869b2cb18635c0a73f3fa72c8bd1f652be8f3304fa711d40f80b42f7')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000192', '22222222-2222-2222-2222-000000000038', 'When implementing Clustering & PCA in Machine Learning, which of the following is considered an anti-pattern or common mistake?', '["Strictly validating input data and handling asynchronous error boundaries gracefully.","Directly mutating internal shared state or ignoring cleanup in asynchronous lifecycles.","Using deterministic pure functions and declarative API contracts.","Profiling execution times and setting appropriate timeout thresholds."]'::jsonb, 1, 'Direct mutation of shared state or leaking asynchronous resources without proper teardown leads to race conditions, memory leaks, and hard-to-trace bugs.', 'medium', 'Machine Learning', 'Clustering & PCA', 'question_bank', 'Identify common anti-patterns and memory/concurrency pitfalls in Clustering & PCA.', '17be939a7471c50fb0f59e1ede6acd48b131365ca2e9b1e20b936ce28c617030')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000193', '22222222-2222-2222-2222-000000000038', 'What is the expected behavior or time/space tradeoff when optimizing Clustering & PCA under high load?', '["Memory consumption is completely reduced to zero while throughput increases infinitely.","Trading additional memory/caching to achieve lower latency and avoid redundant CPU-intensive computations.","Switching to an unindexed linear scan to reduce disk I/O overhead.","Removing thread pools and running all concurrent tasks on a single unmonitored thread."]'::jsonb, 1, 'Classic performance optimization in Machine Learning leverages space-time tradeoffs: caching computed state or indexing reduces CPU bottleneck at the expense of bounded memory.', 'medium', 'Machine Learning', 'Clustering & PCA', 'question_bank', 'Evaluate algorithmic and resource trade-offs in Clustering & PCA.', 'fae16f8cd1d552318c59dfd1085b83081a04e7176725160fc7027e6db964661e')
ON CONFLICT (question_hash) DO NOTHING;
