VALUES ('33333333-3333-3333-3333-000000000218', '22222222-2222-2222-2222-000000000043', 'What is the expected behavior or time/space tradeoff when optimizing Vector Search & Embeddings under high load?', '["Memory consumption is completely reduced to zero while throughput increases infinitely.","Trading additional memory/caching to achieve lower latency and avoid redundant CPU-intensive computations.","Switching to an unindexed linear scan to reduce disk I/O overhead.","Removing thread pools and running all concurrent tasks on a single unmonitored thread."]'::jsonb, 1, 'Classic performance optimization in RAG Architecture leverages space-time tradeoffs: caching computed state or indexing reduces CPU bottleneck at the expense of bounded memory.', 'medium', 'RAG Architecture', 'Vector Search & Embeddings', 'question_bank', 'Evaluate algorithmic and resource trade-offs in Vector Search & Embeddings.', '47deb0e79e18c9b3beea7fb2231b0359adea4710b2ee67525583c6ad8882cfa3')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000219', '22222222-2222-2222-2222-000000000043', 'Which code construct or design pattern is most standard when working with Vector Search & Embeddings?', '["Relying on arbitrary global variables across unrelated modules.","Adhering to Single Responsibility and using structured abstractions with proper error handling.","Hardcoding configuration secrets and database credentials inside client files.","Suppressing exceptions using empty catch blocks to ensure silence."]'::jsonb, 1, 'Modern engineering standards require adherence to SOLID principles, separation of concerns, and robust error propagation.', 'hard', 'RAG Architecture', 'Vector Search & Embeddings', 'question_bank', 'Apply best-practice design patterns for Vector Search & Embeddings.', 'd5f20c953806d8bc15525846d93ebe1c6f05676af92f5b27f023a682a3687bff')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000220', '22222222-2222-2222-2222-000000000043', 'During technical interviews, how should an engineer explain the key advantage of Vector Search & Embeddings over traditional alternatives?', '["It guarantees 100% bug-free execution without requiring any automated tests or peer reviews.","It offers better scalability, modularity, and operational clarity while handling edge cases predictably.","It requires zero compilation or interpretation time regardless of codebase size.","It replaces all database, network, and hardware layers with a single script."]'::jsonb, 1, 'In engineering interviews, evaluating Vector Search & Embeddings centers on scalable architecture, decoupling, maintainability, and predictable failure modes.', 'advanced', 'RAG Architecture', 'Vector Search & Embeddings', 'question_bank', 'Articulate architectural advantages and real-world considerations in interviews.', 'b4796359b0ff5ebe05e3835e28b97432c31fa4dd1c78d0677ab2cb27d7b2951c')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000221', '22222222-2222-2222-2222-000000000044', 'In the context of LLM Adaptation (LoRA & Autonomous Agents), what is the primary architectural purpose or defining characteristic?', '["To encapsulate and modularize LoRA & Autonomous Agents logic for predictable, isolated state and high maintainability.","To eliminate all CPU and memory overhead by converting dynamic execution to purely static bytecode.","To enforce a synchronous blocking execution model across the entire client and server pipeline.","To bypass network security boundaries and grant unrestricted kernel access."]'::jsonb, 0, 'The core design goal of LoRA & Autonomous Agents within LLM Adaptation is providing structured encapsulation, predictability, and clean abstraction boundaries.', 'easy', 'LLM Adaptation', 'LoRA & Autonomous Agents', 'question_bank', 'Understand the fundamental architecture and purpose of LoRA & Autonomous Agents.', '81e4f36a96b67cb55ed2fd49b75fc793f4f0df4cc0877ec31dd9b2d1d7d6662e')
ON CONFLICT (question_hash) DO NOTHING;
