VALUES ('33333333-3333-3333-3333-000000000246', '22222222-2222-2222-2222-000000000049', 'In the context of AWS Serverless (Lambda & API Gateway), what is the primary architectural purpose or defining characteristic?', '["To encapsulate and modularize Lambda & API Gateway logic for predictable, isolated state and high maintainability.","To eliminate all CPU and memory overhead by converting dynamic execution to purely static bytecode.","To enforce a synchronous blocking execution model across the entire client and server pipeline.","To bypass network security boundaries and grant unrestricted kernel access."]'::jsonb, 0, 'The core design goal of Lambda & API Gateway within AWS Serverless is providing structured encapsulation, predictability, and clean abstraction boundaries.', 'easy', 'AWS Serverless', 'Lambda & API Gateway', 'question_bank', 'Understand the fundamental architecture and purpose of Lambda & API Gateway.', '972440a91e219e49c754815108389aa62036f606297cfbaf830a95564dc40610')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000247', '22222222-2222-2222-2222-000000000049', 'When implementing Lambda & API Gateway in AWS Serverless, which of the following is considered an anti-pattern or common mistake?', '["Strictly validating input data and handling asynchronous error boundaries gracefully.","Directly mutating internal shared state or ignoring cleanup in asynchronous lifecycles.","Using deterministic pure functions and declarative API contracts.","Profiling execution times and setting appropriate timeout thresholds."]'::jsonb, 1, 'Direct mutation of shared state or leaking asynchronous resources without proper teardown leads to race conditions, memory leaks, and hard-to-trace bugs.', 'medium', 'AWS Serverless', 'Lambda & API Gateway', 'question_bank', 'Identify common anti-patterns and memory/concurrency pitfalls in Lambda & API Gateway.', 'bfd00bc79b57de6c7f7d85ae81c404cf2c5ed31f8276cfad178eb3eee3428718')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000248', '22222222-2222-2222-2222-000000000049', 'What is the expected behavior or time/space tradeoff when optimizing Lambda & API Gateway under high load?', '["Memory consumption is completely reduced to zero while throughput increases infinitely.","Trading additional memory/caching to achieve lower latency and avoid redundant CPU-intensive computations.","Switching to an unindexed linear scan to reduce disk I/O overhead.","Removing thread pools and running all concurrent tasks on a single unmonitored thread."]'::jsonb, 1, 'Classic performance optimization in AWS Serverless leverages space-time tradeoffs: caching computed state or indexing reduces CPU bottleneck at the expense of bounded memory.', 'medium', 'AWS Serverless', 'Lambda & API Gateway', 'question_bank', 'Evaluate algorithmic and resource trade-offs in Lambda & API Gateway.', '9eea31c44b6744a2502a39a242c294942a8c854704acc58f7c67c63c268e0448')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000249', '22222222-2222-2222-2222-000000000049', 'Which code construct or design pattern is most standard when working with Lambda & API Gateway?', '["Relying on arbitrary global variables across unrelated modules.","Adhering to Single Responsibility and using structured abstractions with proper error handling.","Hardcoding configuration secrets and database credentials inside client files.","Suppressing exceptions using empty catch blocks to ensure silence."]'::jsonb, 1, 'Modern engineering standards require adherence to SOLID principles, separation of concerns, and robust error propagation.', 'hard', 'AWS Serverless', 'Lambda & API Gateway', 'question_bank', 'Apply best-practice design patterns for Lambda & API Gateway.', 'b1cfa9124788e4dee393cbd205fbe09cf28416b907d4d232e16209b25b06d1f4')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000250', '22222222-2222-2222-2222-000000000049', 'During technical interviews, how should an engineer explain the key advantage of Lambda & API Gateway over traditional alternatives?', '["It guarantees 100% bug-free execution without requiring any automated tests or peer reviews.","It offers better scalability, modularity, and operational clarity while handling edge cases predictably.","It requires zero compilation or interpretation time regardless of codebase size.","It replaces all database, network, and hardware layers with a single script."]'::jsonb, 1, 'In engineering interviews, evaluating Lambda & API Gateway centers on scalable architecture, decoupling, maintainability, and predictable failure modes.', 'advanced', 'AWS Serverless', 'Lambda & API Gateway', 'question_bank', 'Articulate architectural advantages and real-world considerations in interviews.', '1c6acb270e500d025eb53981ce8711937099773d913ed3c2e39fff2e96f967dd')
ON CONFLICT (question_hash) DO NOTHING;
