VALUES ('33333333-3333-3333-3333-000000000302', '22222222-2222-2222-2222-000000000060', 'When implementing State Management in Kubernetes Storage, which of the following is considered an anti-pattern or common mistake?', '["Strictly validating input data and handling asynchronous error boundaries gracefully.","Directly mutating internal shared state or ignoring cleanup in asynchronous lifecycles.","Using deterministic pure functions and declarative API contracts.","Profiling execution times and setting appropriate timeout thresholds."]'::jsonb, 1, 'Direct mutation of shared state or leaking asynchronous resources without proper teardown leads to race conditions, memory leaks, and hard-to-trace bugs.', 'medium', 'Kubernetes Storage', 'State Management', 'question_bank', 'Identify common anti-patterns and memory/concurrency pitfalls in State Management.', '10db2a0322b5ba037b2175859001c05412c7dfb570bd6d3ba3e27f05dd5da280')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000303', '22222222-2222-2222-2222-000000000060', 'What is the expected behavior or time/space tradeoff when optimizing State Management under high load?', '["Memory consumption is completely reduced to zero while throughput increases infinitely.","Trading additional memory/caching to achieve lower latency and avoid redundant CPU-intensive computations.","Switching to an unindexed linear scan to reduce disk I/O overhead.","Removing thread pools and running all concurrent tasks on a single unmonitored thread."]'::jsonb, 1, 'Classic performance optimization in Kubernetes Storage leverages space-time tradeoffs: caching computed state or indexing reduces CPU bottleneck at the expense of bounded memory.', 'medium', 'Kubernetes Storage', 'State Management', 'question_bank', 'Evaluate algorithmic and resource trade-offs in State Management.', '24d9855093da1cfd1b2db5155474cd0030e76569e8b51f361630b8961f91e1ba')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000304', '22222222-2222-2222-2222-000000000060', 'Which code construct or design pattern is most standard when working with State Management?', '["Relying on arbitrary global variables across unrelated modules.","Adhering to Single Responsibility and using structured abstractions with proper error handling.","Hardcoding configuration secrets and database credentials inside client files.","Suppressing exceptions using empty catch blocks to ensure silence."]'::jsonb, 1, 'Modern engineering standards require adherence to SOLID principles, separation of concerns, and robust error propagation.', 'hard', 'Kubernetes Storage', 'State Management', 'question_bank', 'Apply best-practice design patterns for State Management.', 'c25ebfa3e5dc54bb1dfa5044d06a3365c51c2744bc8e55e71d2ed194e10148f4')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000305', '22222222-2222-2222-2222-000000000060', 'During technical interviews, how should an engineer explain the key advantage of State Management over traditional alternatives?', '["It guarantees 100% bug-free execution without requiring any automated tests or peer reviews.","It offers better scalability, modularity, and operational clarity while handling edge cases predictably.","It requires zero compilation or interpretation time regardless of codebase size.","It replaces all database, network, and hardware layers with a single script."]'::jsonb, 1, 'In engineering interviews, evaluating State Management centers on scalable architecture, decoupling, maintainability, and predictable failure modes.', 'advanced', 'Kubernetes Storage', 'State Management', 'question_bank', 'Articulate architectural advantages and real-world considerations in interviews.', '13a6a5cb1b49d1b43432c17a318f8b0e0234b3d3a22fb4f5628ec35bb2da5ff5')
ON CONFLICT (question_hash) DO NOTHING;
