INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000331', '22222222-2222-2222-2222-000000000066', 'In the context of Database Design (Normalization 1NF-BCNF), what is the primary architectural purpose or defining characteristic?', '["To encapsulate and modularize Normalization 1NF-BCNF logic for predictable, isolated state and high maintainability.","To eliminate all CPU and memory overhead by converting dynamic execution to purely static bytecode.","To enforce a synchronous blocking execution model across the entire client and server pipeline.","To bypass network security boundaries and grant unrestricted kernel access."]'::jsonb, 0, 'The core design goal of Normalization 1NF-BCNF within Database Design is providing structured encapsulation, predictability, and clean abstraction boundaries.', 'easy', 'Database Design', 'Normalization 1NF-BCNF', 'question_bank', 'Understand the fundamental architecture and purpose of Normalization 1NF-BCNF.', 'cd0fd0d856f9075dff68a2ec4290a7ca5e7b82d98b6f3548b549cbcfa76366a6')
