INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000332', '22222222-2222-2222-2222-000000000066', 'When implementing Normalization 1NF-BCNF in Database Design, which of the following is considered an anti-pattern or common mistake?', '["Strictly validating input data and handling asynchronous error boundaries gracefully.","Directly mutating internal shared state or ignoring cleanup in asynchronous lifecycles.","Using deterministic pure functions and declarative API contracts.","Profiling execution times and setting appropriate timeout thresholds."]'::jsonb, 1, 'Direct mutation of shared state or leaking asynchronous resources without proper teardown leads to race conditions, memory leaks, and hard-to-trace bugs.', 'medium', 'Database Design', 'Normalization 1NF-BCNF', 'question_bank', 'Identify common anti-patterns and memory/concurrency pitfalls in Normalization 1NF-BCNF.', 'fcaecf6f04a6f5d128445884eb5579dff5fe013a7bded55f9374c5b2e77e94e0')
