INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000333', '22222222-2222-2222-2222-000000000066', 'What is the expected behavior or time/space tradeoff when optimizing Normalization 1NF-BCNF under high load?', '["Memory consumption is completely reduced to zero while throughput increases infinitely.","Trading additional memory/caching to achieve lower latency and avoid redundant CPU-intensive computations.","Switching to an unindexed linear scan to reduce disk I/O overhead.","Removing thread pools and running all concurrent tasks on a single unmonitored thread."]'::jsonb, 1, 'Classic performance optimization in Database Design leverages space-time tradeoffs: caching computed state or indexing reduces CPU bottleneck at the expense of bounded memory.', 'medium', 'Database Design', 'Normalization 1NF-BCNF', 'question_bank', 'Evaluate algorithmic and resource trade-offs in Normalization 1NF-BCNF.', '0f938ec2fb9296bb1a3662e6d07c4df5f8a43c0b2e1b6e0995cd4c36e03df485')
