VALUES ('33333333-3333-3333-3333-000000000358', '22222222-2222-2222-2222-000000000071', 'What is the expected behavior or time/space tradeoff when optimizing Git Bisect under high load?', '["Memory consumption is completely reduced to zero while throughput increases infinitely.","Trading additional memory/caching to achieve lower latency and avoid redundant CPU-intensive computations.","Switching to an unindexed linear scan to reduce disk I/O overhead.","Removing thread pools and running all concurrent tasks on a single unmonitored thread."]'::jsonb, 1, 'Classic performance optimization in Troubleshooting leverages space-time tradeoffs: caching computed state or indexing reduces CPU bottleneck at the expense of bounded memory.', 'medium', 'Troubleshooting', 'Git Bisect', 'question_bank', 'Evaluate algorithmic and resource trade-offs in Git Bisect.', '9e0c4ae41e92bd90676ba13d3e4ac8a797871797598ded40fe7967edf126d7f5')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000359', '22222222-2222-2222-2222-000000000071', 'Which code construct or design pattern is most standard when working with Git Bisect?', '["Relying on arbitrary global variables across unrelated modules.","Adhering to Single Responsibility and using structured abstractions with proper error handling.","Hardcoding configuration secrets and database credentials inside client files.","Suppressing exceptions using empty catch blocks to ensure silence."]'::jsonb, 1, 'Modern engineering standards require adherence to SOLID principles, separation of concerns, and robust error propagation.', 'hard', 'Troubleshooting', 'Git Bisect', 'question_bank', 'Apply best-practice design patterns for Git Bisect.', '7d3df9d0c30531791b9f4345df864976435a76d3cb02fedbc9d8a26fcbec154a')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000360', '22222222-2222-2222-2222-000000000071', 'During technical interviews, how should an engineer explain the key advantage of Git Bisect over traditional alternatives?', '["It guarantees 100% bug-free execution without requiring any automated tests or peer reviews.","It offers better scalability, modularity, and operational clarity while handling edge cases predictably.","It requires zero compilation or interpretation time regardless of codebase size.","It replaces all database, network, and hardware layers with a single script."]'::jsonb, 1, 'In engineering interviews, evaluating Git Bisect centers on scalable architecture, decoupling, maintainability, and predictable failure modes.', 'advanced', 'Troubleshooting', 'Git Bisect', 'question_bank', 'Articulate architectural advantages and real-world considerations in interviews.', 'c16a5bb8bf4e4eda653f35bebcf6eb6673b65706e0e2221addf26789b9aa8e49')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000361', '22222222-2222-2222-2222-000000000072', 'In the context of Collaboration (Trunk-Based vs GitFlow), what is the primary architectural purpose or defining characteristic?', '["To encapsulate and modularize Trunk-Based vs GitFlow logic for predictable, isolated state and high maintainability.","To eliminate all CPU and memory overhead by converting dynamic execution to purely static bytecode.","To enforce a synchronous blocking execution model across the entire client and server pipeline.","To bypass network security boundaries and grant unrestricted kernel access."]'::jsonb, 0, 'The core design goal of Trunk-Based vs GitFlow within Collaboration is providing structured encapsulation, predictability, and clean abstraction boundaries.', 'easy', 'Collaboration', 'Trunk-Based vs GitFlow', 'question_bank', 'Understand the fundamental architecture and purpose of Trunk-Based vs GitFlow.', '83e2d4378d3d003edf1cb854ca9ca3255c09775241f1ff9a61625732d9a37001')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000362', '22222222-2222-2222-2222-000000000072', 'When implementing Trunk-Based vs GitFlow in Collaboration, which of the following is considered an anti-pattern or common mistake?', '["Strictly validating input data and handling asynchronous error boundaries gracefully.","Directly mutating internal shared state or ignoring cleanup in asynchronous lifecycles.","Using deterministic pure functions and declarative API contracts.","Profiling execution times and setting appropriate timeout thresholds."]'::jsonb, 1, 'Direct mutation of shared state or leaking asynchronous resources without proper teardown leads to race conditions, memory leaks, and hard-to-trace bugs.', 'medium', 'Collaboration', 'Trunk-Based vs GitFlow', 'question_bank', 'Identify common anti-patterns and memory/concurrency pitfalls in Trunk-Based vs GitFlow.', 'ba83c71873d5bbacf4a308a775cdcd98524fd5d33a6c2af73cf54061480f59bf')
