INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000416', '22222222-2222-2222-2222-000000000083', 'In the context of Memory Management (Paging & TLB), what is the primary architectural purpose or defining characteristic?', '["To encapsulate and modularize Paging & TLB logic for predictable, isolated state and high maintainability.","To eliminate all CPU and memory overhead by converting dynamic execution to purely static bytecode.","To enforce a synchronous blocking execution model across the entire client and server pipeline.","To bypass network security boundaries and grant unrestricted kernel access."]'::jsonb, 0, 'The core design goal of Paging & TLB within Memory Management is providing structured encapsulation, predictability, and clean abstraction boundaries.', 'easy', 'Memory Management', 'Paging & TLB', 'question_bank', 'Understand the fundamental architecture and purpose of Paging & TLB.', '84503bb8de031184c8723b9c4fa15cd7dd04c61ebb485be81884abc0dc96b36a')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000417', '22222222-2222-2222-2222-000000000083', 'When implementing Paging & TLB in Memory Management, which of the following is considered an anti-pattern or common mistake?', '["Strictly validating input data and handling asynchronous error boundaries gracefully.","Directly mutating internal shared state or ignoring cleanup in asynchronous lifecycles.","Using deterministic pure functions and declarative API contracts.","Profiling execution times and setting appropriate timeout thresholds."]'::jsonb, 1, 'Direct mutation of shared state or leaking asynchronous resources without proper teardown leads to race conditions, memory leaks, and hard-to-trace bugs.', 'medium', 'Memory Management', 'Paging & TLB', 'question_bank', 'Identify common anti-patterns and memory/concurrency pitfalls in Paging & TLB.', 'b0f73514470799ae334b8009fbab1f63d18e9ccb7147bb64178fbb9e62c24fb4')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000418', '22222222-2222-2222-2222-000000000083', 'What is the expected behavior or time/space tradeoff when optimizing Paging & TLB under high load?', '["Memory consumption is completely reduced to zero while throughput increases infinitely.","Trading additional memory/caching to achieve lower latency and avoid redundant CPU-intensive computations.","Switching to an unindexed linear scan to reduce disk I/O overhead.","Removing thread pools and running all concurrent tasks on a single unmonitored thread."]'::jsonb, 1, 'Classic performance optimization in Memory Management leverages space-time tradeoffs: caching computed state or indexing reduces CPU bottleneck at the expense of bounded memory.', 'medium', 'Memory Management', 'Paging & TLB', 'question_bank', 'Evaluate algorithmic and resource trade-offs in Paging & TLB.', '8c4e7f0f0493241c5e2f0abac0facdd5e338d27aa1f90631abf757336810a0e9')
