ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000443', '22222222-2222-2222-2222-000000000088', 'What is the expected behavior or time/space tradeoff when optimizing Disk Storage & Indexes under high load?', '["Memory consumption is completely reduced to zero while throughput increases infinitely.","Trading additional memory/caching to achieve lower latency and avoid redundant CPU-intensive computations.","Switching to an unindexed linear scan to reduce disk I/O overhead.","Removing thread pools and running all concurrent tasks on a single unmonitored thread."]'::jsonb, 1, 'Classic performance optimization in Storage Engines leverages space-time tradeoffs: caching computed state or indexing reduces CPU bottleneck at the expense of bounded memory.', 'medium', 'Storage Engines', 'Disk Storage & Indexes', 'question_bank', 'Evaluate algorithmic and resource trade-offs in Disk Storage & Indexes.', '421b9ad297223b2e51c9fc44494020284822784d1677fb40ec7f25578fd4be39')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000444', '22222222-2222-2222-2222-000000000088', 'Which code construct or design pattern is most standard when working with Disk Storage & Indexes?', '["Relying on arbitrary global variables across unrelated modules.","Adhering to Single Responsibility and using structured abstractions with proper error handling.","Hardcoding configuration secrets and database credentials inside client files.","Suppressing exceptions using empty catch blocks to ensure silence."]'::jsonb, 1, 'Modern engineering standards require adherence to SOLID principles, separation of concerns, and robust error propagation.', 'hard', 'Storage Engines', 'Disk Storage & Indexes', 'question_bank', 'Apply best-practice design patterns for Disk Storage & Indexes.', 'd1db2744153f4d1d6dff76755e7417d0c73c972b810a42ed4032d796210c1a79')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000445', '22222222-2222-2222-2222-000000000088', 'During technical interviews, how should an engineer explain the key advantage of Disk Storage & Indexes over traditional alternatives?', '["It guarantees 100% bug-free execution without requiring any automated tests or peer reviews.","It offers better scalability, modularity, and operational clarity while handling edge cases predictably.","It requires zero compilation or interpretation time regardless of codebase size.","It replaces all database, network, and hardware layers with a single script."]'::jsonb, 1, 'In engineering interviews, evaluating Disk Storage & Indexes centers on scalable architecture, decoupling, maintainability, and predictable failure modes.', 'advanced', 'Storage Engines', 'Disk Storage & Indexes', 'question_bank', 'Articulate architectural advantages and real-world considerations in interviews.', 'b3ae251c3825d417b5e0834e41f2ffe0fdcf14ee4adf6a1afa5550cff223ac50')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000446', '22222222-2222-2222-2222-000000000089', 'In the context of Software Design (SOLID Principles), what is the primary architectural purpose or defining characteristic?', '["To encapsulate and modularize SOLID Principles logic for predictable, isolated state and high maintainability.","To eliminate all CPU and memory overhead by converting dynamic execution to purely static bytecode.","To enforce a synchronous blocking execution model across the entire client and server pipeline.","To bypass network security boundaries and grant unrestricted kernel access."]'::jsonb, 0, 'The core design goal of SOLID Principles within Software Design is providing structured encapsulation, predictability, and clean abstraction boundaries.', 'easy', 'Software Design', 'SOLID Principles', 'question_bank', 'Understand the fundamental architecture and purpose of SOLID Principles.', 'b0a9e36189507b301fd4dc0a201dadb1caf0dad9010677efcbc955c8f6c641f7')
ON CONFLICT (question_hash) DO NOTHING;
