ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000471', '22222222-2222-2222-2222-000000000094', 'In the context of Behavioral Interviews (STAR Framework), what is the primary architectural purpose or defining characteristic?', '["To encapsulate and modularize STAR Framework logic for predictable, isolated state and high maintainability.","To eliminate all CPU and memory overhead by converting dynamic execution to purely static bytecode.","To enforce a synchronous blocking execution model across the entire client and server pipeline.","To bypass network security boundaries and grant unrestricted kernel access."]'::jsonb, 0, 'The core design goal of STAR Framework within Behavioral Interviews is providing structured encapsulation, predictability, and clean abstraction boundaries.', 'easy', 'Behavioral Interviews', 'STAR Framework', 'question_bank', 'Understand the fundamental architecture and purpose of STAR Framework.', '8bf47f9986589c63a78d0ca896cc09e80225e6ba600f9efc0084e63d8dd31db3')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000472', '22222222-2222-2222-2222-000000000094', 'When implementing STAR Framework in Behavioral Interviews, which of the following is considered an anti-pattern or common mistake?', '["Strictly validating input data and handling asynchronous error boundaries gracefully.","Directly mutating internal shared state or ignoring cleanup in asynchronous lifecycles.","Using deterministic pure functions and declarative API contracts.","Profiling execution times and setting appropriate timeout thresholds."]'::jsonb, 1, 'Direct mutation of shared state or leaking asynchronous resources without proper teardown leads to race conditions, memory leaks, and hard-to-trace bugs.', 'medium', 'Behavioral Interviews', 'STAR Framework', 'question_bank', 'Identify common anti-patterns and memory/concurrency pitfalls in STAR Framework.', 'cbecf5f3219bdb72aec6b7f37ad42c4cda0682b704713acb59a097d2678f9a0a')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000473', '22222222-2222-2222-2222-000000000094', 'What is the expected behavior or time/space tradeoff when optimizing STAR Framework under high load?', '["Memory consumption is completely reduced to zero while throughput increases infinitely.","Trading additional memory/caching to achieve lower latency and avoid redundant CPU-intensive computations.","Switching to an unindexed linear scan to reduce disk I/O overhead.","Removing thread pools and running all concurrent tasks on a single unmonitored thread."]'::jsonb, 1, 'Classic performance optimization in Behavioral Interviews leverages space-time tradeoffs: caching computed state or indexing reduces CPU bottleneck at the expense of bounded memory.', 'medium', 'Behavioral Interviews', 'STAR Framework', 'question_bank', 'Evaluate algorithmic and resource trade-offs in STAR Framework.', '1dcdba721b997b62478011f8558ebf6ad3dde308b1edc965135502e6472b6419')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000474', '22222222-2222-2222-2222-000000000094', 'Which code construct or design pattern is most standard when working with STAR Framework?', '["Relying on arbitrary global variables across unrelated modules.","Adhering to Single Responsibility and using structured abstractions with proper error handling.","Hardcoding configuration secrets and database credentials inside client files.","Suppressing exceptions using empty catch blocks to ensure silence."]'::jsonb, 1, 'Modern engineering standards require adherence to SOLID principles, separation of concerns, and robust error propagation.', 'hard', 'Behavioral Interviews', 'STAR Framework', 'question_bank', 'Apply best-practice design patterns for STAR Framework.', '57b89e1f61f255a51d4ce0bb37cb11e1eee5f756dcd4b982148b9cf6a964b9dc')
ON CONFLICT (question_hash) DO NOTHING;
