VALUES ('33333333-3333-3333-3333-000000000499', '22222222-2222-2222-2222-000000000099', 'Which code construct or design pattern is most standard when working with Probability?', '["Relying on arbitrary global variables across unrelated modules.","Adhering to Single Responsibility and using structured abstractions with proper error handling.","Hardcoding configuration secrets and database credentials inside client files.","Suppressing exceptions using empty catch blocks to ensure silence."]'::jsonb, 1, 'Modern engineering standards require adherence to SOLID principles, separation of concerns, and robust error propagation.', 'hard', 'Combinatorics', 'Probability', 'question_bank', 'Apply best-practice design patterns for Probability.', '71d239f73e98a5264a3e99b80ac15e2cd7b02d73f06d88ac5df83e0ff6dd9e87')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000500', '22222222-2222-2222-2222-000000000099', 'During technical interviews, how should an engineer explain the key advantage of Probability over traditional alternatives?', '["It guarantees 100% bug-free execution without requiring any automated tests or peer reviews.","It offers better scalability, modularity, and operational clarity while handling edge cases predictably.","It requires zero compilation or interpretation time regardless of codebase size.","It replaces all database, network, and hardware layers with a single script."]'::jsonb, 1, 'In engineering interviews, evaluating Probability centers on scalable architecture, decoupling, maintainability, and predictable failure modes.', 'advanced', 'Combinatorics', 'Probability', 'question_bank', 'Articulate architectural advantages and real-world considerations in interviews.', 'aa63597dd368a5d32d8b565a3e6007ef144fdb7ec314130b34c7358654ccbf5c')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000501', '22222222-2222-2222-2222-000000000100', 'In the context of Logical Reasoning (Puzzles & Syllogisms), what is the primary architectural purpose or defining characteristic?', '["To encapsulate and modularize Puzzles & Syllogisms logic for predictable, isolated state and high maintainability.","To eliminate all CPU and memory overhead by converting dynamic execution to purely static bytecode.","To enforce a synchronous blocking execution model across the entire client and server pipeline.","To bypass network security boundaries and grant unrestricted kernel access."]'::jsonb, 0, 'The core design goal of Puzzles & Syllogisms within Logical Reasoning is providing structured encapsulation, predictability, and clean abstraction boundaries.', 'easy', 'Logical Reasoning', 'Puzzles & Syllogisms', 'question_bank', 'Understand the fundamental architecture and purpose of Puzzles & Syllogisms.', 'e4cf0f5947dda48df6affe07f644821065b9a4fa46c26e8dfaf4a41a38c42509')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000502', '22222222-2222-2222-2222-000000000100', 'When implementing Puzzles & Syllogisms in Logical Reasoning, which of the following is considered an anti-pattern or common mistake?', '["Strictly validating input data and handling asynchronous error boundaries gracefully.","Directly mutating internal shared state or ignoring cleanup in asynchronous lifecycles.","Using deterministic pure functions and declarative API contracts.","Profiling execution times and setting appropriate timeout thresholds."]'::jsonb, 1, 'Direct mutation of shared state or leaking asynchronous resources without proper teardown leads to race conditions, memory leaks, and hard-to-trace bugs.', 'medium', 'Logical Reasoning', 'Puzzles & Syllogisms', 'question_bank', 'Identify common anti-patterns and memory/concurrency pitfalls in Puzzles & Syllogisms.', '646fe795f01783478c8d76a1fed8cf7632f8f6662899ad0ac3186286250ebc67')
ON CONFLICT (question_hash) DO NOTHING;
INSERT INTO public.questions (id, module_id, question, options, correct_answer, explanation, difficulty, topic, subtopic, source, learning_objective, question_hash)
VALUES ('33333333-3333-3333-3333-000000000503', '22222222-2222-2222-2222-000000000100', 'What is the expected behavior or time/space tradeoff when optimizing Puzzles & Syllogisms under high load?', '["Memory consumption is completely reduced to zero while throughput increases infinitely.","Trading additional memory/caching to achieve lower latency and avoid redundant CPU-intensive computations.","Switching to an unindexed linear scan to reduce disk I/O overhead.","Removing thread pools and running all concurrent tasks on a single unmonitored thread."]'::jsonb, 1, 'Classic performance optimization in Logical Reasoning leverages space-time tradeoffs: caching computed state or indexing reduces CPU bottleneck at the expense of bounded memory.', 'medium', 'Logical Reasoning', 'Puzzles & Syllogisms', 'question_bank', 'Evaluate algorithmic and resource trade-offs in Puzzles & Syllogisms.', 'e36071842c50edc2170db4cfac5ec0ec81a0117f0dfe91feba517975e4f12edf')
